VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: word begins with a vowel, "xr", or "yt".
    if word[0] in VOWELS or word.startswith("xr") or word.startswith("yt"):
        return word + "ay"

    # Rules 2-4: move the leading consonant cluster to the end.
    # "qu" counts as part of the cluster (Rule 3), and "y" is treated
    # as a vowel when it is not the first letter (Rule 4).
    i = 0
    while i < len(word) and word[i] not in VOWELS:
        if word[i] == "q" and i + 1 < len(word) and word[i + 1] == "u":
            i += 2
            break
        i += 1
    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())

